vy(a,b){return"\u05d9\u05d9\u05d5\u05d5\u05e6\u05e8\u05d5 "+a+" \u05e7\u05d1\u05d5\u05e6\u05d5\u05ea \u05d7\u05d3\u05e9\u05d5\u05ea \u05d5\u05d9\u05ea\u05d5\u05d5\u05e1\u05e4\u05d5 "+b+" \u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9\u05dd"},
